#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n,a[100005],res;//atted表示是否发出过攻击  
int p,v[100005],q[100005],w;
//v[i]表示第i小的没有攻击过的数的数量，q[i]表示数字i是第几大的 
int main(){
	freopen("duel.in","r",stdin);
	freopen("duel.out","w",stdout);
	scanf("%d",&n);
	res=n;
	for(int i=1;i<=n;i++){
		scanf("%d",&a[i]);
	}
	//预处理 
	sort(a+1,a+n+1);
	p=1;q[a[1]]=p;v[p]=1;
	for(int i=2;i<=n;i++){
		if(a[i-1]!=a[i]){//和上一项不相同 
			p++; 
			q[a[i]]=p;
//			cout<<i<<" "<<a[i]<<" "<<p<<" "<<q[a[i]]<<endl;;
		}
		v[p]++;
	}

	for(int i=1;i<n;i++){//be attected
		w=q[a[i]];//a[i]的位次 
		w++;
		if(w>p){//到头了啥都没了别加了 
			printf("%d",res);
			return 0; 
		}
		while(v[w]==0){
			if(w==p){//到头了啥都没了别加了 
				printf("%d",res);
				return 0; 
			}
			w++;
		}
		v[w]--;//往上一个档次的能发起攻击的-1 
		res--; 
	}
//	for(int i=1;i<=n;i++){
//		printf("%d ",a[i]);
//	}cout<<endl;
//	for(int i=1;i<=n;i++){
//		printf("%d ",v[i]);
//	}cout<<endl;
	printf("%d\n",res);
	fclose(stdin);fclose(stdout);
	return 0; 
}
